import {useEffect,useRef,useState} from 'react';
import {ArrowLeft,ArrowRight,ArrowUpRight,Award,BookOpen,Check,CheckCheck,ChevronDown,ChevronRight,Clock3,FileText,FolderOpen,GitBranch,GripVertical,HelpCircle,Layers3,ListChecks,LogOut,MapPin,Menu,MessageCircle,NotebookPen,Plus,RotateCcw,Search,ShieldCheck,Users,Volume2,VolumeX,Wrench,X} from 'lucide-react';
import {CASE_MATERIALS,CAUSE_CANDIDATES,CATEGORIES,EVENT_CARDS,EVIDENCE_CARDS,FIRST_OPTIONS,INTERVIEW,INTERVIEW_INTRO,QUESTIONS,REQUIRED_TOPICS,SCENE_OBJECTS,STAGES,WHY_PROMPTS,whyOptions,Category,QuestionId} from './assessment-data';
import {CaseState,CauseNode,WhyAnswer,EMPTY_CASE,answerDecision,canAttach,caseScore,changeTree,classificationCount,collectEvidence,correctedCount,deleteNode,finishStage,moveTimeline,placeEvidence,restoreCase,saveWhy,stageReady,timelineIssue,topicCount,treeIssues} from './assessment-state';
import {useCaseDrag} from './use-case-drag';
import {Chip,Note} from './teaching-board';
import CaseScene from './case-scene';
import CaseTree from './case-tree';

const KEY='samruk-case001-v2';
type Status={tone:'success'|'review'|'info';title:string;text:string};
type Modal={kind:'evidence'|'journal'|'node'|'stageReport'|'badge'|'restart'|'guide';id?:string};
const EMPTY_WHY:WhyAnswer={key:'',text:'',path:'open',verify:''};
function PersonPhoto({person}:{person:'worker'|'witness'}){return <div className={`person-photo ${person}`}><img src="/assets/participants.webp" alt={person==='worker'?'Пострадавший работник':'Свидетель происшествия'} draggable={false}/></div>}

export default function Assessment({onCourse,onSignOut}:{onCourse:()=>void;onSignOut:()=>void}){
 const [state,setState]=useState<CaseState>(()=>restoreCase(null));const [loaded,setLoaded]=useState(false);const [canSave,setCanSave]=useState(true);
 const [menu,setMenu]=useState(false);const [status,setStatus]=useState<Status|null>(null);const [modal,setModal]=useState<Modal|null>(null);
 const [decision,setDecision]=useState<string|null>(null);const [selected,setSelected]=useState<string|null>(null);
 const [sourceTab,setSourceTab]=useState<'scene'|'people'|'journal'>('scene');const [question,setQuestion]=useState<QuestionId|null>(null);
 const [whyIndex,setWhyIndex]=useState(0);const [whyDraft,setWhyDraft]=useState<WhyAnswer>(EMPTY_WHY);const [whyHint,setWhyHint]=useState(false);
 const [nodeDraft,setNodeDraft]=useState<CauseNode|null>(null);const [sound,setSound]=useState(false);const audio=useRef<AudioContext|null>(null);
 const dialogRef=useRef<HTMLDivElement>(null);const headingRef=useRef<HTMLHeadingElement>(null);
 const stage=STAGES[state.stage-1];const ready=stageReady(state);const score=caseScore(state);
 const completedPct=Math.round(state.completed.length/10*100);const selectedCard=EVIDENCE_CARDS.find(c=>c.id===selected);
 const classesDone=classificationCount(state);const whysCount=state.whys.filter(Boolean).length;

 useEffect(()=>{try{setState(restoreCase(JSON.parse(localStorage.getItem(KEY)||'null')));setSound(localStorage.getItem(KEY+'-sound')==='1')}catch{setCanSave(false)}finally{setLoaded(true)}},[]);
 useEffect(()=>{if(!loaded)return;try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-sound',sound?'1':'0')}catch{setCanSave(false)}},[state,sound,loaded]);
 useEffect(()=>{setDecision(state.decisionPassed?'b':null);setSelected(null);setStatus(null);setMenu(false);setWhyHint(false);if(state.stage===8){const i=state.whys.findIndex(a=>!a);setWhyIndex(i<0?5:i);setWhyDraft(i<0?EMPTY_WHY:state.whys[i]||EMPTY_WHY)}},[state.stage,loaded]);
 useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const el=dialogRef.current;el?.querySelector<HTMLButtonElement>('button')?.focus();function trap(e:KeyboardEvent){if(e.key==='Escape'){setModal(null);return}if(e.key!=='Tab'||!el)return;const all=Array.from(el.querySelectorAll<HTMLElement>('button:not([disabled]),input,textarea,select,a[href]')).filter(x=>x.getBoundingClientRect().height>0);const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}document.addEventListener('keydown',trap);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',trap);if(previous?.isConnected)previous.focus()}},[modal]);
 function cue(){if(!sound||!window.AudioContext)return;try{audio.current??=new AudioContext();const a=audio.current;void a.resume();const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=620;g.gain.setValueAtTime(.025,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.13);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.14)}catch{}}
 function notify(tone:Status['tone'],title:string,text:string){setStatus({tone,title,text})}
 function goStage(n:number){if(n<1||n>state.furthest)return;setState(s=>({...s,stage:n}));setModal(null);setMenu(false);setStatus(null);window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>headingRef.current?.focus({preventScroll:true}))}
 function advance(){if(!ready)return;setState(s=>finishStage(s));setStatus(null);setSelected(null);window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>headingRef.current?.focus({preventScroll:true}));cue()}
 function inspect(id:string){if(SCENE_OBJECTS.some(o=>o.id===id))setState(s=>({...s,found:Array.from(new Set([...s.found,id]))}));setModal({kind:'evidence',id})}
 function chooseCard(id:string){if(state.placements[id]){inspect(id);return}setSelected(id===selected?null:id);setStatus(null)}
 function classify(id:string,category:Category){const r=placeEvidence(state,id,category);setState(s=>placeEvidence(s,id,category).state);notify(r.correct?'success':'review',r.correct?'Карточка распределена':'Сверьте категорию',r.message);if(r.correct){setSelected(null);cue()}}
 function timelinePlace(id:string,target:number){setState(s=>moveTimeline(s,id,target));setSelected(null);setStatus(null)}
 function addNode(id:string,parent='incident'){
  if(state.nodes.some(n=>n.id===id))return;const c=CAUSE_CANDIDATES.find(n=>n.id===id);if(!c)return;
  const n:CauseNode={...c,parent,evidence:'',reason:''};setState(s=>changeTree(s,[...s.nodes,n]));notify('info',c.question?'Добавлен вопрос к проверке':'Добавлена гипотеза',c.question?'Вопрос помещён в план проверок. Он не является причинным узлом.':'Откройте карточку, чтобы указать материал и обоснование связи.');cue();
 }
 function editNode(id:string){const n=state.nodes.find(n=>n.id===id);if(!n)return;setNodeDraft({...n});setModal({kind:'node',id})}
 function moveNode(id:string,parent:string){if(!canAttach(state.nodes,id,parent)){notify('review','Такую связь создать нельзя','Узел нельзя связать с самим собой, своим потомком или вопросом к проверке.');return}setState(s=>changeTree(s,s.nodes.map(n=>n.id===id?{...n,parent,reason:n.parent===parent?n.reason:''}:n)));setStatus(null)}
 const drag=useCaseDrag((id,target)=>{
  if(state.stage===5&&target.startsWith('category:'))classify(id,target.slice(9) as Category);
  if(state.stage===7&&(target.startsWith('slot:')||target==='timeline-bank'))timelinePlace(id,target==='timeline-bank'?-1:Number(target.slice(5)));
  if(state.stage===9&&target.startsWith('node:')){const parent=target.slice(5);if(id.startsWith('candidate:'))addNode(id.slice(10),parent);else if(id.startsWith('node:'))moveNode(id.slice(5),parent)}
 });
 const dragLabel=drag.drag?(EVIDENCE_CARDS.find(c=>c.id===drag.drag?.id)?.title||EVENT_CARDS.find(c=>c.id===drag.drag?.id)?.title||CAUSE_CANDIDATES.find(c=>'candidate:'+c.id===drag.drag?.id)?.title||state.nodes.find(c=>'node:'+c.id===drag.drag?.id)?.title||'Карточка'):'';
 function ask(id:QuestionId){setQuestion(id);setState(s=>({...s,asked:Array.from(new Set([...s.asked,id]))}));setStatus(null);cue()}
 function editWhy(i:number){if(i<0||i>4||(i>0&&!state.whys[i-1]))return;setWhyIndex(i);setWhyDraft(state.whys[i]||EMPTY_WHY);setWhyHint(false);setStatus(null)}
 function importWhys(){const imported=state.whys.flatMap((a,i)=>a&&!state.nodes.some(n=>n.id==='why-'+i)?[{id:'why-'+i,title:a.text,parent:i===0?'incident':'why-'+(i-1),evidence:'',reason:'Проверить: '+a.verify,question:false}]:[]);setState(s=>changeTree(s,[...s.nodes,...imported]));notify('info','Версии перенесены','Цепочка добавлена как гипотезы. Материалы и связи ещё нужно проверить.');}
 function gate(id:string,value:'and'|'or'|''){setState(s=>{const gates={...s.gates};if(value)gates[id]=value;else delete gates[id];return changeTree(s,s.nodes,gates)});setStatus(null)}
 function act(){
  if(state.stage===3&&!state.decisionPassed){if(!decision)return;setState(s=>answerDecision(s,decision));const a=FIRST_OPTIONS.find(o=>o.id===decision)!;notify(decision==='b'?'success':'review',decision==='b'?'Верно · +20 баллов':decision==='g'?'Частично верно':'Решение нужно пересмотреть',a.feedback);if(decision==='b')cue();return;}
  if(state.stage===5&&!state.peopleIntroduced){setState(s=>({...s,peopleIntroduced:true}));window.scrollTo({top:0,behavior:'instant'});return;}
  if(state.stage===7&&!state.timelineSaved){if(!state.timelineChecked){const issue=timelineIssue(state.timeline);setState(s=>({...s,timelineAttempts:s.timelineAttempts+1,timelineChecked:!issue}));if(issue)notify('review','Уточните порядок событий',issue);else notify('success','Учебная последовательность согласована','Порядок соответствует рабочей реконструкции сценария. Точные времена большинства событий и механизм отклонения ещё требуют проверки.');}else{setState(s=>({...s,timelineSaved:true}));notify('success','Хронология сохранена','Карточки и их источники будут доступны на следующих этапах.');cue()}return;}
  if(state.stage===8&&whyIndex<5){if(!whyDraft.text.trim()||!whyDraft.verify.trim())return;const s=saveWhy(state,whyIndex,whyDraft);setState(s);const next=whyIndex+1;setWhyIndex(next);setWhyDraft(next<5?s.whys[next]||EMPTY_WHY:EMPTY_WHY);setWhyHint(false);setStatus(null);cue();return;}
  if(state.stage===8&&whyIndex===5&&!state.whysSaved){if(!state.whys.every(Boolean))return;setState(s=>({...s,whysSaved:true}));notify('success','Цепочка подтверждена','Версии и способы проверки сохранены с учётом обновлённой хронологии.');cue();return;}
  if(state.stage===9&&!state.treeSaved){if(!state.treeChecked){const issues=treeIssues(state);if(issues.length){notify('review','Уточните схему',issues.join(' '));return}setState(s=>({...s,treeChecked:true}));const h=state.nodes.filter(n=>!n.question);notify('success','Структура схемы проверена',`Материалы указаны для ${h.filter(n=>n.evidence).length} из ${h.length} гипотез, обоснования — для ${h.filter(n=>n.reason.trim()).length} связей. Схема остаётся предварительной.`);}else{setState(s=>({...s,treeSaved:true}));notify('success','Предварительная схема сохранена','Гипотезы, связи и план проверок сохранены для отчёта.');cue()}return;}
  advance();
 }
 const actionLabel=state.stage===1?'Начать расследование':state.stage===2?'К первому решению':state.stage===3?state.decisionPassed?'К осмотру места происшествия':'Подтвердить выбор':state.stage===4?'К классификации':state.stage===5?!state.peopleIntroduced?'К классификации':'К интервью со свидетелем':state.stage===6?'К хронологии':state.stage===7?state.timelineSaved?'К анализу причин':state.timelineChecked?'Сохранить хронологию':'Проверить порядок':state.stage===8?whyIndex===5?state.whysSaved?'К дереву причин':'Подтвердить цепочку':whyIndex===4?'Сохранить цепочку':'Сохранить и продолжить':state.stage===9?state.treeSaved?'К итогам расследования':state.treeChecked?'Сохранить схему':'Проверить схему':'Вернуться в курс';
 const actionDisabled=state.stage===2?!state.managerRead:state.stage===3?!state.decisionPassed&&!decision:state.stage===4?!ready:state.stage===5?state.peopleIntroduced&&!ready:state.stage===6?!ready:state.stage===7?state.timeline.some(x=>!x):state.stage===8?whyIndex===5?!state.whys.every(Boolean):!whyDraft.text.trim()||!whyDraft.verify.trim():state.stage===9?!state.nodes.some(n=>!n.question):false;
 const actionHint=state.stage===4?`В журнале ${state.collected.length} из 8 записей`:state.stage===5&&state.peopleIntroduced?`${classesDone} из 8 карточек распределено`:state.stage===6?`Уточнено ${topicCount(state)} из 3 тем`:state.stage===7?'Точное время известно не для всех событий':state.stage===8?'Каждая версия остаётся предметом проверки':state.stage===9?'Проверяем структуру предварительной модели':'Ваши решения сохраняются в этом браузере';
 useEffect(()=>{function keys(e:KeyboardEvent){if(modal||menu)return;const t=e.target as HTMLElement;if(['INPUT','TEXTAREA','SELECT'].includes(t.tagName)||t.isContentEditable)return;if(state.stage===3&&!state.decisionPassed&&/^[1-4]$/.test(e.key)){e.preventDefault();setDecision(FIRST_OPTIONS[Number(e.key)-1].id);setStatus(null)}if(state.stage===5&&selected&&/^[1-4]$/.test(e.key)){e.preventDefault();classify(selected,CATEGORIES[Number(e.key)-1].id)}if(state.stage===7&&selected&&/^[1-6]$/.test(e.key)){e.preventDefault();timelinePlace(selected,Number(e.key)-1)}if(e.key==='Escape'){setSelected(null);setMenu(false)}}window.addEventListener('keydown',keys);return()=>window.removeEventListener('keydown',keys)});

 const badges=[
  {id:'first',title:'Первое решение',earned:state.decisionPassed,rule:'Выбрать сбор доказательств и проверку обстоятельств вместо принятия предварительной версии.'},
  {id:'evidence',title:'Сбор доказательств',earned:state.collected.length===8,rule:'Изучить и добавить в журнал все восемь записей осмотра.'},
  {id:'interview',title:'Интервью',earned:topicCount(state)===3,rule:'Уточнить личные наблюдения, приблизительное время и других людей поблизости.'},
  {id:'timeline',title:'Хронология',earned:state.timelineSaved,rule:'Проверить и сохранить рабочую последовательность шести карточек.'},
  {id:'analysis',title:'Анализ причин',earned:state.whysSaved&&state.treeSaved,rule:'Сохранить пять версий со способами проверки и предварительную схему причин.'},
  {id:'leader',title:'Руководитель расследования',earned:[1,2,3,4,5,6,7,8,9].every(n=>state.completed.includes(n)),rule:'Завершить все этапы учебного кейса. Знак отмечает прохождение, а не профессиональную аттестацию.'}
 ];
 const reports=[
  {id:3,title:'Первое решение',value:state.decisionPassed?'1 из 1':'0 из 1',text:state.decisionAttempts.length===1?'Верный подход выбран с первой попытки.':`Попыток: ${state.decisionAttempts.length}. Предварительную версию удалось отделить от фактов.`,points:state.decisionPassed?20:0},
  {id:4,title:'Сбор доказательств',value:`${state.collected.length} из 8`,text:'Наблюдения и документы из осмотра сохранены в журнале.',points:null},
  {id:5,title:'Классификация «Четыре П»',value:`${classesDone} из 8`,text:correctedCount(state)?`Неверных попыток размещения: ${correctedCount(state)}. Вы исправили классификацию.`:'Карточки распределены без неверных попыток.',points:classesDone*10},
  {id:6,title:'Интервью со свидетелем',value:`${topicCount(state)} из 3 тем`,text:state.asked.includes('leading')?'Был задан наводящий вопрос. Свидетель не подтвердил неисправность; это ограничение сохранено.':'Уточнены границы личного наблюдения, время и другие участники.',points:null},
  {id:7,title:'Построение хронологии',value:state.timelineSaved?'6 из 6':'Не сохранено',text:`Проверок порядка: ${state.timelineAttempts}. Около 09:42 — время наблюдения свидетеля; остальные отметки требуют уточнения.`,points:null},
  {id:8,title:'Метод «Пять почему»',value:`${whysCount} из 5`,text:'Сохранены версии и сведения, которые нужны для проверки каждой связи.',points:null},
  {id:9,title:'Дерево причин',value:state.treeSaved?'Сохранено':'Не сохранено',text:`Гипотез: ${state.nodes.filter(n=>!n.question).length}. Вопросов к проверке: ${state.nodes.filter(n=>n.question).length}. Схема предварительная.`,points:null}
 ];

 function journalContent(){return <div className="case-journal-content"><p className="eyebrow">ОСМОТР · {state.collected.length} ЗАПИСЕЙ</p>{SCENE_OBJECTS.filter(o=>state.collected.includes(o.id)).map(o=><button className="journal-entry" key={o.id} onClick={()=>inspect(o.id)}><span>{o.number}</span><div><strong>{o.title}</strong><p>{o.description}</p></div><ArrowUpRight size={14}/></button>)}{state.asked.length>0&&<><p className="eyebrow journal-section-title">ПОКАЗАНИЯ СВИДЕТЕЛЯ</p>{state.asked.map(id=><div className={`journal-note ${id==='leading'?'caution':''}`} key={id}><strong>{INTERVIEW[id].noteTitle}</strong><p>{INTERVIEW[id].note}</p></div>)}</>}{state.timelineSaved&&<><p className="eyebrow journal-section-title">РАБОЧАЯ ХРОНОЛОГИЯ</p>{state.timeline.map((id,i)=><div className="journal-timeline" key={id}><span>{i+1}</span><div><strong>{EVENT_CARDS.find(e=>e.id===id)?.title}</strong><p>{EVENT_CARDS.find(e=>e.id===id)?.time}</p></div></div>)}</>}</div>}
 function reportDetails(id:number){if(id===3)return <><p className="case-modal-intro">Ваши попытки выбора первого действия.</p>{state.decisionAttempts.map((a,i)=><div className="report-detail" key={i}><Chip tone={a==='b'?'green':'amber'}>Попытка {i+1}</Chip><h3>{FIRST_OPTIONS.find(o=>o.id===a)?.text}</h3><p>{FIRST_OPTIONS.find(o=>o.id===a)?.feedback}</p></div>)}</>;if(id===4)return journalContent();if(id===5)return <div className="report-classifications">{EVIDENCE_CARDS.map(c=><div key={c.id}><strong>{c.title}</strong><span>{CATEGORIES.find(cat=>cat.id===state.placements[c.id])?.title||'Не распределено'}</span><small>Неверных попыток: {state.classificationErrors[c.id]||0}</small></div>)}</div>;if(id===6)return <>{state.asked.map(q=><div className="report-detail" key={q}><h3>{QUESTIONS.find(x=>x.id===q)?.text}</h3><blockquote>«{INTERVIEW[q].reply}»</blockquote><p>{INTERVIEW[q].feedback}</p></div>)}</>;if(id===7)return <>{state.timeline.map((id,i)=><div className="report-detail" key={id}><Chip>{i+1}</Chip><h3>{EVENT_CARDS.find(e=>e.id===id)?.title}</h3><p>{EVENT_CARDS.find(e=>e.id===id)?.time} · {EVENT_CARDS.find(e=>e.id===id)?.source}</p></div>)}<Note amber>Это рабочая реконструкция. Фактический механизм отклонения и точное время большинства событий не установлены.</Note></>;if(id===8)return <>{state.whys.map((a,i)=>a&&<div className="report-detail" key={i}><Chip tone="amber">Почему {i+1} · версия</Chip><h3>{a.text}</h3><p><strong>Проверить:</strong> {a.verify}</p></div>)}</>;return <>{state.nodes.map(n=><div className="report-detail" key={n.id}><Chip tone="amber">{n.question?'Вопрос к проверке':'Гипотеза'}</Chip><h3>{n.title}</h3><p>Связь: {n.parent==='incident'?'Выброс рабочей среды':state.nodes.find(x=>x.id===n.parent)?.title||'Не указана'}</p><p>Материал: {CASE_MATERIALS.find(m=>m.id===n.evidence)?.title||'Пока не указан'}</p><p>{n.reason||'Обоснование пока не указано.'}</p></div>)}</>}

 return <div className="app-shell assessment-shell">
  <a className="skip-link" href="#case-main">К содержанию этапа</a>
  <header className="site-header"><button className="brand brand-button" onClick={onCourse} aria-label="Вернуться к лекциям"><div className="brand-mark"><Layers3 size={25}/></div><div><strong>SAMRUK</strong><span>BUSINESS ACADEMY</span></div></button><div className="header-course"><span/>САМОСТОЯТЕЛЬНОЕ РАССЛЕДОВАНИЕ</div><div className="header-actions"><button className="icon-label case-course-link" onClick={onCourse} aria-label="К лекциям"><BookOpen size={17}/><span>К лекциям</span></button><button className="icon-button" aria-label={sound?'Выключить звук':'Включить звук'} aria-pressed={sound} onClick={()=>{setSound(!sound);if(!sound&&window.AudioContext){audio.current??=new AudioContext();void audio.current.resume()}}}>{sound?<Volume2 size={18}/>:<VolumeX size={18}/>}</button><button className="mobile-menu icon-button" aria-label="Этапы расследования" onClick={()=>setMenu(!menu)}><Menu size={23}/></button><button className="icon-button signout-button" aria-label="Выйти" onClick={onSignOut}><LogOut size={17}/></button></div></header>
  <div className="workspace">{menu&&<button className="sidebar-scrim" aria-label="Закрыть этапы расследования" onClick={()=>setMenu(false)}/>}
   <aside className={`sidebar assessment-nav ${menu?'is-open':''}`} aria-label="Этапы расследования"><div className="sidebar-intro"><p className="eyebrow">ПРАКТИЧЕСКАЯ ЧАСТЬ<span>10</span></p><h2>CASE 001</h2><p>Выброс на насосе P-204</p></div><nav>{STAGES.map(s=><button key={s.id} disabled={s.id>state.furthest} className={`case-stage-nav ${state.stage===s.id?'active':''} ${state.completed.includes(s.id)?'done':''}`} onClick={()=>goStage(s.id)} aria-current={state.stage===s.id?'step':undefined}><span>{state.completed.includes(s.id)?<Check size={14}/>:String(s.id).padStart(2,'0')}</span><strong>{s.short}</strong>{state.stage===s.id&&<ChevronRight size={14}/>}</button>)}</nav><div className="case-sidebar-tools"><button onClick={()=>setModal({kind:'journal'})}><NotebookPen size={17}/>Журнал расследования<ArrowUpRight size={13}/></button><button onClick={onCourse}><BookOpen size={17}/>Вернуться к лекциям<ArrowUpRight size={13}/></button></div><div className="sidebar-bottom"><div><span>Прохождение кейса</span><strong>{completedPct}%</strong></div><div className="progress-track"><i style={{width:completedPct+'%'}}/></div><p><CheckCheck size={14}/>{!loaded?'Загружаем прохождение':canSave?'Сохраняется на этом устройстве':'Прогресс в текущей вкладке'}</p><button className="reset-link" onClick={()=>setModal({kind:'restart'})}><RotateCcw size={12}/>Начать кейс заново</button></div></aside>
   <main id="case-main" className="lesson-main assessment-main"><div className="lesson-kicker"><div><span className="module-tag">CASE 001</span><span className="kicker-divider"/>ЭТАП {String(state.stage).padStart(2,'0')} / 10</div><div className="case-top-tools"><button className="source-button" onClick={()=>setModal({kind:'journal'})}><FolderOpen size={16}/>Журнал<span className="source-count">{state.collected.length}</span></button><span className="case-score"><Award size={15}/><strong>{score}</strong><span>/ 100</span></span></div></div>
    <div className="scene-heading case-heading"><div><h1 ref={headingRef} tabIndex={-1}>{state.stage===1?'Расследование происшествия':stage.title}</h1><p>{stage.caption}</p></div><button className="icon-button case-guide" aria-label="О работе с кейсом" onClick={()=>setModal({kind:'guide'})}><HelpCircle size={20}/></button></div>

    {state.stage===1&&<section className="case-cover case-panel"><div className="case-cover-copy"><Chip tone="green">САМОСТОЯТЕЛЬНЫЙ КЕЙС</Chip><h2>От первого сообщения<br/>до модели причин.</h2><p>На производственном объекте произошло происшествие. Соберите доказательства, восстановите ход событий и определите, какие причины нужно проверить.</p><div className="case-role"><ShieldCheck size={24}/><div><span>ВАША РОЛЬ</span><strong>Руководитель группы расследования</strong></div></div><div className="cover-facts"><span><Clock3 size={16}/>15–20 минут</span><span><ListChecks size={16}/>10 этапов</span></div><Note>В учебном сценарии реагирование уже организовано, доступ к материалам и осмотру разрешён.</Note></div><div className="case-cover-art"><img src="/assets/dispatch.webp" alt="Диспетчерский центр производственного объекта"/><span>Диспетчерский центр · Поступило сообщение</span></div></section>}

    {state.stage===2&&<div className="notification-layout"><section className="case-panel incident-notification"><div className="case-panel-head"><h2>Оперативное оповещение</h2><Chip tone="amber">Участок остановлен</Chip></div><div className="notification-body"><div className="incident-time"><span>ВРЕМЯ СООБЩЕНИЯ</span><strong>09:42</strong></div><div className="incident-detail-grid"><div><span>Оборудование</span><strong>Насос P-204</strong></div><div><span>Место</span><strong>Производственный участок</strong></div></div><h3>Выброс рабочей среды</h3><p>Инцидент произошёл во время технических работ. Один работник получил травму. Участок временно остановлен.</p><div className="case-task"><Search size={22}/><div><span>ВАША ЗАДАЧА</span><strong>Организовать расследование происшествия</strong></div></div></div></section><section className="case-panel manager-message"><div className="case-panel-head"><h2>Руководитель производства</h2><MessageCircle size={18}/></div><div className="manager-body">{state.managerRead?<><Chip tone="amber">Предварительная версия</Chip><blockquote>«По предварительной информации, работник не выполнил установленную процедуру. Просим провести расследование и установить причины произошедшего».</blockquote><Note amber>Эта версия требует проверки по материалам расследования.</Note></>:<div className="unread-message"><MessageCircle size={43}/><h3>Получено сообщение</h3><p>Ознакомьтесь с предварительной информацией руководителя.</p><button className="secondary-button" onClick={()=>{setState(s=>({...s,managerRead:true}));cue()}}>Открыть сообщение<ArrowRight size={16}/></button></div>}</div></section></div>}

    {state.stage===3&&<div className="decision-layout"><section className="case-panel decision-context"><div className="case-panel-head"><h2>Первичная информация</h2></div><div className="decision-context-body"><Chip tone="amber">Предварительная версия</Chip><blockquote>«По предварительной информации, работник не выполнил установленную процедуру».</blockquote><p>Руководитель производства</p><div className="decision-question"><Search size={27}/><h3>Какое действие вы предпримете в первую очередь?</h3></div></div></section><section className="case-panel decision-options"><div className="case-panel-head"><h2>Выберите одно действие</h2><span className="eyebrow">КЛАВИШИ 1–4</span></div><div className="answer-options" role="radiogroup" aria-label="Первое действие расследования">{FIRST_OPTIONS.map((o,i)=><button key={o.id} role="radio" aria-checked={decision===o.id} disabled={state.decisionPassed} className={`answer-option ${decision===o.id?'selected':''} ${state.decisionPassed&&o.id==='b'?'correct':''}`} onClick={()=>{setDecision(o.id);setStatus(null)}}><span className="answer-letter">{state.decisionPassed&&o.id==='b'?<Check size={17}/>:o.letter}</span><span>{o.text}</span><small>{i+1}</small></button>)}</div>{status?.tone==='review'&&<button className="text-retry" onClick={()=>{setDecision(null);setStatus(null)}}><RotateCcw size={14}/>Попробовать снова</button>}</section></div>}

    {state.stage===4&&<div className="inspection-layout"><section className="case-panel inspection-photo"><CaseScene variant="inspect" state={state} selected={modal?.kind==='evidence'?modal.id||null:null} onInspect={inspect} onSelect={()=>{}}/><div className="inspection-caption"><p>Нажмите на метку, изучите объект и добавьте запись в журнал.</p><span><Check size={14}/>Изучено {state.studied.length} / 8</span></div></section><aside className="case-panel inspection-journal"><div className="case-panel-head"><h2>Журнал доказательств</h2><Chip>{state.collected.length} / 8</Chip></div><div className="inspection-counts"><span>Найдено объектов<strong>{state.found.length} / 8</strong></span><span>Добавлено в журнал<strong>{state.collected.length} / 8</strong></span></div><div className="inspection-journal-list">{state.collected.length?SCENE_OBJECTS.filter(o=>state.collected.includes(o.id)).map(o=><button key={o.id} className="saved-evidence" onClick={()=>inspect(o.id)}><span>{o.number}</span><div><strong>{o.title}</strong><small>Сохранено в журнале</small></div><ArrowUpRight size={13}/></button>):<div className="empty-journal"><NotebookPen size={33}/><h3>Первые наблюдения</h3><p>Записи появятся здесь после изучения объекта и добавления в журнал.</p></div>}</div></aside></div>}

    {state.stage===5&&!state.peopleIntroduced&&<section className="people-intro"><div className="people-intro-copy"><p className="eyebrow">ПЕРЕД КЛАССИФИКАЦИЕЙ</p><h2>Работник и свидетель</h2><p>В материалах дела появились две карточки. Ознакомьтесь с ними, прежде чем распределять доказательства.</p></div><div className="people-intro-grid"><article className="case-panel person-intro-card"><PersonPhoto person="worker"/><div><Chip>Участник происшествия</Chip><h3>Пострадавший работник</h3><p>Выполнял технические работы на участке насоса P-204. Получил травму при выбросе рабочей среды.</p></div></article><article className="case-panel person-intro-card"><PersonPhoto person="witness"/><div><Chip>Источник сведений</Chip><h3>Свидетель происшествия</h3><p>Работал на соседнем участке. На интервью вы сможете уточнить, что он наблюдал лично.</p></div></article></div></section>}

    {state.stage===5&&state.peopleIntroduced&&<><div className="classification-summary"><p>Перетащите объект прямо из сцены в категорию. Можно также выбрать карточку и нажать на категорию.</p><span><strong>{classesDone}</strong> / 8 распределено</span><span><strong>{classesDone*10}</strong> баллов за этап</span></div><div className="classification-layout"><section className="case-panel classification-sources"><div className="case-source-tabs" role="tablist" aria-label="Источники карточек">{[['scene','Место происшествия'],['people','Работник и свидетель'],['journal','Журнал']].map(([id,title])=><button key={id} role="tab" aria-selected={sourceTab===id} className={sourceTab===id?'active':''} onClick={()=>setSourceTab(id as typeof sourceTab)}>{title}</button>)}</div>{sourceTab==='scene'?<CaseScene variant="classify" state={state} selected={selected} onInspect={inspect} onSelect={chooseCard} drag={drag}/>:sourceTab==='people'?<div className="people-source-grid">{(['worker','witness'] as const).map(id=>{const card=EVIDENCE_CARDS.find(c=>c.id===id)!;const placed=!!state.placements[id];return <button key={id} {...drag.bind(id,()=>chooseCard(id))} className={`person-source draggable-source ${selected===id?'selected':''} ${placed?'placed':''}`} aria-label={`Выбрать ${card.title}`}><PersonPhoto person={id}/><div><span>{placed?'Распределено':'Выбрать или перетащить'}</span><h3>{card.title}</h3>{placed?<Check size={16}/>:<GripVertical size={15}/>}</div></button>})}</div>:<div className="classification-journal">{EVIDENCE_CARDS.map(c=><button key={c.id} {...drag.bind(c.id,()=>chooseCard(c.id))} className={`evidence-source draggable-source ${selected===c.id?'selected':''} ${state.placements[c.id]?'placed':''}`} aria-label={`Выбрать ${c.title}`}><GripVertical size={15}/><strong>{c.title}</strong>{state.placements[c.id]?<Check size={15}/>:<Plus size={14}/>}</button>)}<p className="eyebrow observation-heading">ДОПОЛНИТЕЛЬНЫЕ НАБЛЮДЕНИЯ</p>{SCENE_OBJECTS.filter(o=>o.id==='valve'||o.id==='panel').map(o=><button key={o.id} className="observation-note" onClick={()=>inspect(o.id)}><FileText size={15}/><span>{o.title}</span><ArrowUpRight size={13}/></button>)}</div>}<div className="selected-evidence"><div><span className="eyebrow">ВЫБРАННАЯ КАРТОЧКА</span><strong>{selectedCard?.title||'Выберите объект или запись'}</strong></div><button className="secondary-button" disabled={!selectedCard} onClick={()=>selectedCard&&inspect(selectedCard.id)}>Открыть карточку<ArrowUpRight size={14}/></button></div>{sourceTab==='scene'&&<p className="case-source-note">Серые метки 2 и 3 открывают наблюдения из журнала. Они не входят в восемь карточек для распределения.</p>}</section><section className="classification-categories" aria-label="Категории Четыре П">{CATEGORIES.map((c,i)=>{const Icon=[MapPin,Users,Wrench,FileText][i];const placed=EVIDENCE_CARDS.filter(e=>state.placements[e.id]===c.id);return <div key={c.id} data-case-drop={'category:'+c.id} className={`case-category ${drag.over==='category:'+c.id?'drop-over':''}`}><button className="category-target" onClick={()=>selected?classify(selected,c.id):notify('info','Сначала выберите карточку','Нажмите на объект сцены, человека или запись в журнале.')} aria-label={`Поместить в категорию ${c.title}`}><Icon size={22}/><div><h3>{c.title}</h3><p>{c.hint}</p></div><span>{placed.length}</span></button>{placed.length>0&&<div className="placed-evidence-list">{placed.map(e=><button key={e.id} onClick={()=>inspect(e.id)}><Check size={12}/>{e.title}<ArrowUpRight size={11}/></button>)}</div>}<div className="category-drop-hint">{selected?'Нажмите, чтобы поместить выбранное':'Перетащите карточку сюда'}<small>{i+1}</small></div></div>})}</section></div></>}

    {state.stage===6&&<div className="interview-layout"><section className="case-panel witness-panel"><div className="witness-person"><PersonPhoto person="witness"/><div><Chip>Источник сведений</Chip><h2>Свидетель происшествия</h2><p>Сотрудник соседнего участка</p></div></div>{question&&<div className="interviewer-message"><span>ВЫ</span><p>{QUESTIONS.find(q=>q.id===question)?.text}</p></div>}<div className="witness-message"><span>СВИДЕТЕЛЬ</span><p>«{question?INTERVIEW[question].reply:INTERVIEW_INTRO}»</p></div>{question&&<div className={`interview-feedback ${question==='leading'?'caution':''}`}><strong>{INTERVIEW[question].title}</strong><p>{INTERVIEW[question].feedback}</p></div>}</section><aside className="case-panel interview-questions"><div className="case-panel-head"><h2>Вопросы свидетелю</h2></div><div className="interview-question-list">{QUESTIONS.map((q,i)=><button key={q.id} className={question===q.id?'selected':''} onClick={()=>ask(q.id)}><span>{String(i+1).padStart(2,'0')}</span><strong>{q.text}</strong>{state.asked.includes(q.id)?<Check size={15}/>:<ChevronRight size={15}/>}</button>)}</div><div className="interview-progress"><div><span>Уточнено тем</span><strong>{topicCount(state)} из 3</strong></div><div className="progress-track"><i style={{width:topicCount(state)/3*100+'%'}}/></div><p>Личное наблюдение · время · другие люди</p></div></aside><section className="case-panel interview-notes"><div className="case-panel-head"><h2>Показания в журнале</h2><NotebookPen size={18}/></div><div className="interview-notes-grid"><div className="journal-note"><strong>Вступительное показание</strong><p>Видел подготовку бригады, позже услышал звук и заметил выброс.</p></div>{state.asked.map(id=><button key={id} className={`journal-note ${id==='leading'?'caution':''}`} onClick={()=>setQuestion(id)}><strong>{INTERVIEW[id].noteTitle}</strong><p>{INTERVIEW[id].note}</p></button>)}</div></section></div>}

    {state.stage===7&&<><div className="case-instruction"><GripVertical size={18}/><p>Перетащите событие из журнала или выберите карточку и место на шкале. Карточки можно переставлять.</p></div><div className="case-timeline-layout"><aside className={`case-panel event-bank ${drag.over==='timeline-bank'?'drop-over':''}`} data-case-drop="timeline-bank"><div className="case-panel-head"><h2>Журнал расследования</h2><Chip>{6-state.timeline.filter(Boolean).length} карточек</Chip></div><div className="event-bank-body">{EVENT_CARDS.filter(e=>!state.timeline.includes(e.id)).map(e=><button key={e.id} {...drag.bind(e.id,()=>setSelected(selected===e.id?null:e.id))} className={`event-card draggable-source ${selected===e.id?'selected':''} ${e.kind==='hypothesis'?'hypothesis-event':''}`} aria-label={`Выбрать событие ${e.title}`}><GripVertical size={14}/><div><strong>{e.title}</strong><p>{e.description}</p><span><Clock3 size={11}/>{e.time}</span><small>{e.source}</small></div></button>)}{state.timeline.every(Boolean)&&<div className="empty-journal"><CheckCheck size={32}/><p>Все карточки на шкале.<br/>Их порядок можно изменить.</p></div>}</div><button className="return-to-bank" disabled={!selected} onClick={()=>selected&&timelinePlace(selected,-1)}><ArrowLeft size={15}/>Вернуть выбранное в журнал</button></aside><section className="case-panel timeline-workspace"><div className="case-panel-head"><div><h2>Временная шкала</h2><p>Рабочая реконструкция · от раннего к позднему</p></div><Chip>{state.timeline.filter(Boolean).length} / 6</Chip></div><div className="timeline-slots">{state.timeline.map((id,i)=>{const event=EVENT_CARDS.find(e=>e.id===id);return <div key={i} className={`timeline-slot ${drag.over==='slot:'+i?'drop-over':''}`} data-case-drop={'slot:'+i}><span className="timeline-slot-number">{String(i+1).padStart(2,'0')}</span>{event?<><button {...drag.bind(event.id,()=>{if(selected&&selected!==event.id)timelinePlace(selected,i);else setSelected(selected===event.id?null:event.id)})} className={`timeline-event draggable-source ${selected===event.id?'selected':''} ${event.kind==='hypothesis'?'hypothesis-event':''}`} aria-label={`Событие на позиции ${i+1}: ${event.title}`}><GripVertical size={14}/><div><strong>{event.title}</strong><span>{event.time}</span><small>{event.source}</small></div></button><button className="slot-remove" aria-label={`Вернуть ${event.title} в журнал`} onClick={()=>timelinePlace(event.id,-1)}><X size={14}/></button></>:<button className="empty-timeline-slot" aria-label={`Поместить карточку на позицию ${i+1}`} onClick={()=>selected?timelinePlace(selected,i):notify('info','Выберите событие','Сначала выберите карточку в журнале.')}><Plus size={18}/><span>Поместить карточку</span></button>}</div>})}</div><Note amber>Отклонение — рабочая гипотеза. Его механизм и время не установлены. Около 09:42 свидетель заметил выброс; это не точное время его возникновения.</Note></section></div></>}

    {state.stage===8&&<><div className="case-incident-strip"><Chip>ИСХОДНОЕ СОБЫТИЕ</Chip><p>Во время технических работ на насосе P-204 произошёл выброс рабочей среды.</p><button onClick={()=>setModal({kind:'journal'})}><FolderOpen size={16}/>Материалы<ArrowUpRight size={12}/></button></div><div className="why-layout"><aside className="case-panel why-chain"><div className="case-panel-head"><h2>Цепочка вопросов</h2><Chip>{whysCount} / 5</Chip></div><div>{WHY_PROMPTS.map((p,i)=><button key={i} disabled={i>0&&!state.whys[i-1]} className={`why-chain-step ${whyIndex===i?'active':''} ${state.whys[i]?'saved':''}`} onClick={()=>editWhy(i)}><span>{state.whys[i]?<Check size={14}/>:String(i+1).padStart(2,'0')}</span><div><h3>Почему {i+1}</h3><p>{state.whys[i]?.text||p.topic}</p><small>{state.whys[i]?'Версия сохранена':i===whyIndex?'Текущий вопрос':'Ожидает предыдущего ответа'}</small></div></button>)}</div></aside><section className="case-panel why-editor">{whyIndex===5?<div className="why-saved-summary"><div className="round-symbol"><CheckCheck size={31}/></div><Chip tone="green">5 из 5 вопросов</Chip><h2>{state.whysSaved?'Цепочка сохранена':'Перепроверьте цепочку'}</h2><p>{state.whysSaved?'Версии и способы их проверки сохранены для текущего прохождения. Любой шаг можно открыть и изменить.':'Хронология изменилась. Откройте нужные шаги, проверьте версии и подтвердите цепочку.'}</p><Note amber>Эта цепочка не устанавливает коренную причину. Каждая связь остаётся гипотезой до проверки.</Note></div>:<div className="why-editor-body"><p className="eyebrow">ВОПРОС {String(whyIndex+1).padStart(2,'0')} ИЗ 05 · {WHY_PROMPTS[whyIndex].topic}</p><h2>{WHY_PROMPTS[whyIndex].question}</h2>{whyIndex>0&&<div className="previous-why"><span>ПРЕДЫДУЩЕЕ ПРЕДПОЛОЖЕНИЕ</span><p>{state.whys[whyIndex-1]?.text}</p></div>}<p className="why-choice-label">Выберите или запишите предположение</p><div className="answer-options" role="radiogroup" aria-label={`Предположение для вопроса ${whyIndex+1}`}>{whyOptions(whyIndex,state.whys[whyIndex-1]?.path).map((choice,i)=><button key={i} role="radio" aria-checked={whyDraft.key===String(i)} className={`answer-option ${whyDraft.key===String(i)?'selected':''}`} onClick={()=>setWhyDraft({key:String(i),...choice})}><span className="answer-letter">{i+1}</span><span>{choice.text}</span></button>)}<button role="radio" aria-checked={whyDraft.key==='own'} className={`answer-option ${whyDraft.key==='own'?'selected':''}`} onClick={()=>setWhyDraft({key:'own',text:whyDraft.key==='own'?whyDraft.text:'',path:'open',verify:whyDraft.key==='own'?whyDraft.verify:''})}><span className="answer-letter"><NotebookPen size={14}/></span><span>Свой вариант</span></button></div>{whyDraft.key==='own'&&<label className="case-field"><span>Ваше предположение</span><textarea aria-label="Ваше предположение" value={whyDraft.text} maxLength={1200} rows={3} onChange={e=>setWhyDraft(d=>({...d,text:e.target.value}))} placeholder="Сформулируйте проверяемую версию…"/></label>}{whyDraft.key&&<div className="why-verification"><Chip tone="amber">Требует проверки</Chip><p>Данный вывод пока не подтверждён. Какие сведения нужны для проверки этой версии и её связи с предыдущим шагом?</p><label className="case-field"><span>Что нужно проверить</span><textarea aria-label="Что нужно проверить" rows={3} maxLength={2000} value={whyDraft.verify} onChange={e=>setWhyDraft(d=>({...d,verify:e.target.value}))} placeholder="Укажите запись, наблюдение или показание и вопрос к нему…"/></label></div>}{state.whys[whyIndex]&&state.whys.slice(whyIndex+1).some(Boolean)&&<p className="why-edit-warning">При изменении версии следующие ответы будут сброшены. Импортированные версии дерева потребуется добавить заново.</p>}<button className="hint-toggle" aria-expanded={whyHint} onClick={()=>setWhyHint(!whyHint)}><HelpCircle size={15}/>{whyHint?'Скрыть подсказку':'Подсказка'}<ChevronDown size={14}/></button>{whyHint&&<Note>{WHY_PROMPTS[whyIndex].hint}</Note>}</div>}</section></div></>}

    {state.stage===9&&<><div className="case-instruction"><GitBranch size={19}/><p>Свяжите гипотезы с событием, выберите логику ветвей и укажите материалы для проверки. Карточки можно перетаскивать или редактировать.</p></div><CaseTree state={state} drag={drag} onAdd={addNode} onEdit={editNode} onGate={gate} onImport={importWhys}/></>}

    {state.stage===10&&<div className="case-results"><section className="case-result-hero case-panel"><div><Chip tone="green"><CheckCheck size={12}/>CASE 001 · ЗАВЕРШЕНО</Chip><h2>Ваше расследование<br/>завершено.</h2><p>Вы разобрали происшествие на насосе P-204 и составили предварительную схему. Причины и связи ещё нужно проверить по дополнительным материалам.</p></div><div className="result-score"><span>ПЕРВОЕ РЕШЕНИЕ И ЧЕТЫРЕ П</span><strong>{score}<small>/ 100</small></strong><p>баллов за два оцениваемых этапа</p><div><CheckCheck size={16}/>Прохождение кейса {completedPct}%</div></div></section><section className="case-panel result-stage-list"><div className="case-panel-head"><h2>Результаты по этапам</h2><span className="eyebrow">НАЖМИТЕ ДЛЯ РАЗБОРА</span></div>{reports.map(r=><button key={r.id} onClick={()=>setModal({kind:'stageReport',id:String(r.id)})}><span className="result-stage-number">{String(r.id).padStart(2,'0')}</span><div><h3>{r.title}</h3><p>{r.text}</p></div><span className="result-value">{r.value}{r.points!==null&&<small>{r.points} баллов</small>}</span><ChevronRight size={17}/></button>)}</section><section className="case-achievements"><div><h2>Достижения прохождения</h2><p>Откройте знак, чтобы увидеть условие получения.</p></div><div className="achievement-grid">{badges.map((b,i)=>{const Icon=[Search,FolderOpen,MessageCircle,Clock3,GitBranch,ShieldCheck][i];return <button key={b.id} className={b.earned?'earned':''} onClick={()=>setModal({kind:'badge',id:b.id})}><span><Icon size={25}/></span><strong>{b.title}</strong><small>{b.earned?'Получен':'Ещё не получен'}</small></button>})}</div></section><div className="next-investigation"><ShieldCheck size={27}/><div><h3>Дальнейшее расследование</h3><p>Проверьте версии по материалам дела. Затем определите обоснованные причины, подготовьте корректирующие мероприятия и порядок проверки их выполнения.</p></div></div><div className="case-result-actions"><button className="primary-button" onClick={()=>setModal({kind:'restart'})}><RotateCcw size={17}/>Повторить расследование</button><button className="secondary-button" onClick={onCourse}><BookOpen size={17}/>Вернуться в курс</button></div></div>}

    {status&&<div className={`case-status ${status.tone}`} role="status" aria-live="polite">{status.tone==='success'?<CheckCheck size={20}/>:status.tone==='review'?<RotateCcw size={20}/>:<HelpCircle size={20}/>}<div><strong>{status.title}</strong><p>{status.text}</p></div></div>}
    {state.stage<10&&<div className="case-action-bar"><button className="back-button" onClick={()=>state.stage===1?onCourse():goStage(state.stage-1)}><ArrowLeft size={16}/>{state.stage===1?'К лекциям':'Назад'}</button><p>{actionHint}</p><button className="primary-button case-next" disabled={actionDisabled} onClick={act}><span>{actionLabel}</span>{state.stage===3&&!state.decisionPassed||state.stage===7&&!state.timelineChecked||state.stage===9&&!state.treeChecked?<Check size={18}/>:<ArrowRight size={18}/>}</button></div>}
    <footer className="lesson-footer case-footer"><span><ShieldCheck size={14}/>Учебный случай. Окончательная причина не установлена.</span><button onClick={onCourse}>Samruk Business Academy · Вернуться в курс<ArrowUpRight size={12}/></button></footer>
   </main>
  </div>
  {drag.drag&&<div className="drag-ghost" style={{left:drag.drag.x+12,top:drag.drag.y+12}}><GripVertical size={16}/><strong>{dragLabel}</strong></div>}
  {modal&&<div className={`drawer-backdrop ${modal.kind==='restart'?'centered':''}`} onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby="case-modal-title" className={`drawer case-modal ${modal.kind==='restart'?'reset-dialog':''}`}><header><div><p className="eyebrow">CASE 001 · МАТЕРИАЛЫ РАССЛЕДОВАНИЯ</p><h2 id="case-modal-title">{modal.kind==='evidence'?'Карточка доказательства':modal.kind==='journal'?'Журнал расследования':modal.kind==='node'?'Карточка схемы':modal.kind==='stageReport'?STAGES[Number(modal.id)-1]?.title:modal.kind==='badge'?'Достижение прохождения':modal.kind==='restart'?'Повторить расследование?':'Как работать с кейсом'}</h2></div><button className="icon-button" aria-label="Закрыть окно" onClick={()=>setModal(null)}><X size={22}/></button></header><div className="drawer-body">
   {modal.kind==='evidence'&&(()=>{const object=SCENE_OBJECTS.find(o=>o.id===modal.id);const card=EVIDENCE_CARDS.find(c=>c.id===modal.id);const title=state.stage===4?object?.title:card?.title||object?.title;const description=state.stage===4?object?.description:card?.description||object?.description;const studied=object&&state.studied.includes(object.id);const collected=object&&state.collected.includes(object.id);return <><Chip>{object?'Объект '+object.number:card?.person?'Материал о человеке':'Запись осмотра'}</Chip><h3 className="evidence-detail-title">{title}</h3>{card?.person?<PersonPhoto person={card.person as 'worker'|'witness'}/>:<div className="evidence-detail-photo"><img src="/assets/pump-room.webp" alt="Учебный участок насоса P-204"/>{object&&<span style={{left:object.bounds[0]+'%',top:object.bounds[1]+'%',width:object.bounds[2]+'%',height:object.bounds[3]+'%'}}/>}</div>}<p className="evidence-detail-description">{description}</p>{object&&(studied||state.stage!==4)&&<div className="evidence-study"><p className="eyebrow">ЧТО ПРОВЕРИТЬ</p><p>{object.study}</p></div>}{state.stage===4&&object&&<div className="evidence-detail-actions"><button className="secondary-button" disabled={!!studied} onClick={()=>setState(s=>({...s,studied:Array.from(new Set([...s.studied,object.id]))}))}>{studied?<Check size={16}/>:<Search size={16}/>}<span>{studied?'Изучено':'Изучить'}</span></button><button className="primary-button" disabled={!studied||!!collected} onClick={()=>{setState(s=>collectEvidence(s,object.id));setModal(null);cue()}}>{collected?<Check size={16}/>:<Plus size={16}/>}<span>{collected?'В журнале':'Добавить в журнал'}</span></button></div>}</>})()}
   {modal.kind==='journal'&&journalContent()}
   {modal.kind==='node'&&nodeDraft&&<><Chip tone="amber">{nodeDraft.question?'Вопрос к проверке':'Гипотеза · Требует проверки'}</Chip><label className="case-field"><span>Формулировка</span><textarea aria-label="Формулировка карточки" rows={3} maxLength={1200} value={nodeDraft.title} onChange={e=>setNodeDraft({...nodeDraft,title:e.target.value})}/></label><label className="case-field"><span>{nodeDraft.question?'К какому узлу относится проверка':'Связать с узлом'}</span><select aria-label="Связать с узлом" value={nodeDraft.parent||''} onChange={e=>setNodeDraft({...nodeDraft,parent:e.target.value||null,reason:e.target.value===state.nodes.find(n=>n.id===nodeDraft.id)?.parent?state.nodes.find(n=>n.id===nodeDraft.id)?.reason||'':''})}><option value="">Без связи</option><option value="incident">Выброс рабочей среды</option>{state.nodes.filter(n=>!n.question&&canAttach(state.nodes,nodeDraft.id,n.id)).map(n=><option key={n.id} value={n.id}>{n.title}</option>)}</select></label><label className="case-field"><span>Материал для проверки</span><select aria-label="Материал для проверки" value={nodeDraft.evidence} onChange={e=>setNodeDraft({...nodeDraft,evidence:e.target.value})}><option value="">Материал пока не указан</option>{CASE_MATERIALS.map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select></label>{nodeDraft.evidence&&<Note>{CASE_MATERIALS.find(m=>m.id===nodeDraft.evidence)?.text}</Note>}<label className="case-field"><span>Обоснование или что нужно уточнить</span><textarea aria-label="Обоснование связи" rows={4} maxLength={2000} value={nodeDraft.reason} onChange={e=>setNodeDraft({...nodeDraft,reason:e.target.value})} placeholder="Почему предполагаете связь? Чем её нужно проверить?"/></label><Note amber>Указание материала не подтверждает причину автоматически. Статус карточки остаётся предварительным.</Note><div className="node-editor-actions"><button className="delete-node" onClick={()=>{setState(s=>deleteNode(s,nodeDraft.id));setModal(null);notify('info','Карточка удалена','Её дочерние гипотезы, если они есть, перенесены в раздел без связи.')}}>Удалить</button><button className="secondary-button" onClick={()=>setModal(null)}>Отмена</button><button className="primary-button" disabled={!nodeDraft.title.trim()||!canAttach(state.nodes,nodeDraft.id,nodeDraft.parent)} onClick={()=>{const n={...nodeDraft,title:nodeDraft.title.trim()};setState(s=>changeTree(s,s.nodes.map(old=>old.id===n.id?n:old)));setModal(null);setStatus(null)}}>Сохранить карточку<Check size={15}/></button></div></>}
   {modal.kind==='stageReport'&&<>{reportDetails(Number(modal.id))}<button className="primary-button report-open-stage" onClick={()=>goStage(Number(modal.id))}>Открыть этап<ArrowRight size={16}/></button></>}
   {modal.kind==='badge'&&(()=>{const b=badges.find(b=>b.id===modal.id);return b?<div className="badge-detail"><div className="round-symbol"><Award size={37}/></div><Chip tone={b.earned?'green':'neutral'}>{b.earned?'Получен':'Ещё не получен'}</Chip><h3>{b.title}</h3><p>{b.rule}</p></div>:null})()}
   {modal.kind==='restart'&&<><p className="case-modal-intro">Начнётся новое прохождение CASE 001. Его решения, журнал, хронология и схема будут очищены. Прогресс лекций и конспект курса сохранятся.</p><div className="reset-actions"><button className="secondary-button" onClick={()=>setModal(null)}>Продолжить текущее</button><button className="primary-button" onClick={()=>{setState(restoreCase(null));setModal(null);setStatus(null);setQuestion(null);setSelected(null);window.scrollTo({top:0,behavior:'instant'})}}><RotateCcw size={16}/>Начать новый кейс</button></div></>}
   {modal.kind==='guide'&&<><div className="guide-overview"><Clock3 size={28}/><div><h3>Около 15–20 минут</h3><p>Самостоятельный учебный кейс из десяти этапов.</p></div></div>{[{title:'Отделяйте сведения и версии',text:'Сообщение руководителя, рассказы людей и видимые следы имеют разные границы. Сохраняйте источник каждого утверждения.'},{title:'Работайте с материалами',text:'Изучайте метки на сцене. На доске «Четыре П» перетаскивайте объекты из иллюстрации, людей и записи журнала. Можно выбрать карточку, а затем категорию.'},{title:'Сохраняйте неопределённость',text:'В хронологии большинство времён неизвестны. В «Пяти почему» и дереве формируйте проверяемые гипотезы, а не окончательный диагноз.'},{title:'Баллы отражают два этапа',text:'За верное первое решение начисляется 20 баллов, за каждую карточку «Четыре П» — 10. Итог показывает реальные действия, повторные попытки и сохранённую модель.'}].map((x,i)=><section className="guide-step" key={x.title}><span>0{i+1}</span><div><h3>{x.title}</h3><p>{x.text}</p></div></section>)}<Note>Реальное реагирование и технические проверки выполняются по утверждённым процедурам организации.</Note></>}
  </div></div></div>}
 </div>;
}
